#include <iostream>
#include <string>
#include <utility>  // For std::move

int main() {
    std::string source = "Hello, World!";  // Original string
    std::string dest = std::move(source);   // Move operation
    // source is now in a valid but unspecified state
    std::cout << "Destination: " << dest << std::endl;  // Likely outputs the string
    std::cout << "Source empty? " << std::boolalpha << source.empty() << std::endl;  // May output true, but not guaranteed
    // Best practice: Reinitialize if needed
    source = "Reset string";  // Safely reuse source
    std::cout << "Source after reset: " << source << std::endl;
    return 0;
}
